(* [comment removed for export] *)
Definition fs_agree_but (ex : list Z) (F F' : bvmap 5 word) : Prop :=
  forall r : reg, fs_callee r = true -> existsb (Z.eqb (bv_unsigned r)) ex = false -> reg_get F' r = reg_get F r.

Lemma fs_agree_but_of_agree : forall ex F F', fs_agree F F' -> fs_agree_but ex F F'.
Proof.
ltac2:(KReplay.run1 (kr_t_Bi_kmkit ()) [] "h01Fh12F'h21Hh32Hrh42_Hh52exh61rp;1p;2p;3p-1p10000p4p710p9p1000\p4p710p10019p4p710p8p1001Up4p7210p10022p4p710p8g002Pj1<Tg0030j10Tg003Uj16Tg004:j11Tg004Xj13Tg005;j2;Tg005gj2:Tg006aj15Tg007\j32Tg0086j27Tg008`j14Tg009=j38Tg009Yj39Tg00:ZR0#<g00;8#0R1#6#1R2%01#0#0#0#0#1#3';R1f1R3f0R4':%32g00;]R5%54g00<=321723#4f5580g00<]525f3R5f2R0P3O2W4W3W6A9503eW2X11W0W5o"). Qed.

Ltac fs_step :=
  first [ progress (rewrite ?fs_reg_get_set; fs_eqb_simp)
        | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (fs_agree_get F1 F2 r H) by reflexivity end
        | match goal with H : fs_agree_but ?ex ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (H r eq_refl eq_refl) end ].

Ltac fs_close :=
  let r := fresh "r" in let Hr := fresh "Hr" in let Hx := fresh "Hx" in
  lazymatch goal with
  | |- fs_agree _ _ => intros r Hr
  | |- fs_agree_but _ _ _ => intros r Hr Hx
  end;
  apply fs_callee_cases in Hr; cbn [map In] in Hr;
  repeat (destruct Hr as [<-|Hr]); [..| destruct Hr];
  try (exfalso; vm_compute in Hx; discriminate Hx);
  repeat fs_step; reflexivity.

