Lemma kel_obj_setrow : forall live (m m' : mem) kel sy sx cy cx data rows r,
  kel_obj live m kel sy sx cy cx data rows -> In r rows ->
  (forall p1 n1 p2 n2, In (p1, n1) live -> In (p2, n2) live -> p1 <> p2 -> p1 + n1 <= p2 \/ p2 + n2 <= p1) ->
  (forall a : word, in_live live (bv_unsigned a) -> ~ (r <= bv_unsigned a < r + 4 * sx) -> m' a = m a) ->
  wmono asegs m m' ->
  kel_obj live m' kel sy sx cy cx data rows.
