Section KMKIT.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.

(* [comment removed for export] *)
Lemma km_chunk_split : forall kel data sy sx rows live0 p n, In (p, n) (km_chunks kel data sy sx rows) ->
